-- Comentarios do CTN, lote 5 (arts. 101 a 126). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 101 and 126 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(101,'','Vigência da legislação tributária no espaço e no tempo','A vigência, no espaço e no tempo, da legislação tributária rege-se pelas disposições legais aplicáveis às normas jurídicas em geral, ressalvado o previsto no Capítulo.'),
(102,'','Extraterritorialidade da legislação tributária','A legislação tributária dos Estados, do Distrito Federal e dos Municípios vigora, no País, fora dos respectivos territórios, nos limites em que lhe reconheçam extraterritorialidade os convênios de que participem, ou do que disponham esta ou outras leis de normas gerais expedidas pela União.'),
(103,'','Início de vigência de normas complementares','Salvo disposição em contrário, entram em vigor os atos administrativos a que se refere o inciso I do art. 100, na data da sua publicação (inciso I); as decisões a que se refere o inciso II do art. 100, quanto a seus efeitos normativos, 30 (trinta) dias após a data da sua publicação (inciso II); e os convênios a que se refere o inciso IV do art. 100, na data neles prevista (inciso III).'),
(104,'','Anterioridade de leis sobre impostos sobre patrimônio ou renda','Entram em vigor no primeiro dia do exercício seguinte àquele em que ocorra a sua publicação os dispositivos de lei, referentes a impostos sobre o patrimônio ou a renda, que instituem ou majoram tais impostos (inciso I), que definem novas hipóteses de incidência (inciso II) e que extinguem ou reduzem isenções, salvo se a lei dispuser de maneira mais favorável ao contribuinte, e observado o disposto no art. 178 (inciso III).'),
(105,'','Aplicação imediata da legislação tributária','A legislação tributária aplica-se imediatamente aos fatos geradores futuros e aos pendentes, assim entendidos aqueles cuja ocorrência tenha tido início mas não esteja completa nos termos do art. 116.'),
(106,'','Aplicação retroativa da lei tributária','A lei aplica-se a ato ou fato pretérito, em qualquer caso, quando seja expressamente interpretativa, excluída a aplicação de penalidade à infração dos dispositivos interpretados (inciso I). Tratando-se de ato não definitivamente julgado, aplica-se quando deixe de defini-lo como infração (inciso II, alínea a); quando deixe de tratá-lo como contrário a qualquer exigência de ação ou omissão, desde que não tenha sido fraudulento e não tenha implicado em falta de pagamento de tributo (alínea b); e quando lhe comine penalidade menos severa que a prevista na lei vigente ao tempo da sua prática (alínea c).'),
(107,'','Interpretação da legislação tributária: consulta e pareceres','A legislação tributária será interpretada conforme o disposto no Capítulo. O § 1º, incluído pela Lei Complementar n. 236, de 2026, dispõe que a resolução de dúvidas acerca da legislação tributária e aduaneira e a fixação de sua interpretação e aplicação serão efetuadas por meio do processo administrativo de solução de consulta ou por pareceres jurídicos, conforme o caso, nos termos da legislação específica. O § 2º dispõe que a solução de consulta e os pareceres jurídicos terão efeitos vinculantes restritos, em cada caso, ao âmbito do órgão que os houver emitido. O § 3º dispõe que a solução da consulta produzirá efeitos exclusivamente em relação ao consulente, sem prejuízo da vinculação da interpretação nela fixada no âmbito do órgão emissor, nos termos do § 2º.'),
(108,'','Integração da legislação tributária','Na ausência de disposição expressa, a autoridade competente para aplicar a legislação tributária utilizará sucessivamente, na ordem indicada, a analogia (inciso I), os princípios gerais de direito tributário (inciso II), os princípios gerais de direito público (inciso III) e a equidade (inciso IV). O § 1º dispõe que o emprego da analogia não poderá resultar na exigência de tributo não previsto em lei. O § 2º dispõe que o emprego da equidade não poderá resultar na dispensa do pagamento de tributo devido.'),
(109,'','Princípios gerais de direito privado','Os princípios gerais de direito privado utilizam-se para pesquisa da definição, do conteúdo e do alcance de seus institutos, conceitos e formas, mas não para definição dos respectivos efeitos tributários.'),
(110,'','Institutos de direito privado e competência tributária','A lei tributária não pode alterar a definição, o conteúdo e o alcance de institutos, conceitos e formas de direito privado, utilizados, expressa ou implicitamente, pela Constituição Federal, pelas Constituições dos Estados, ou pelas Leis Orgânicas do Distrito Federal ou dos Municípios, para definir ou limitar competências tributárias.'),
(111,'','Interpretação literal','Interpreta-se literalmente a legislação tributária que disponha sobre suspensão ou exclusão do crédito tributário (inciso I), outorga de isenção (inciso II) e dispensa do cumprimento de obrigações tributárias acessórias (inciso III).'),
(112,'','Interpretação mais favorável ao acusado','A lei tributária que define infrações, ou lhe comina penalidades, interpreta-se da maneira mais favorável ao acusado, em caso de dúvida quanto à capitulação legal do fato (inciso I); à natureza ou às circunstâncias materiais do fato, ou à natureza ou extensão dos seus efeitos (inciso II); à autoria, imputabilidade ou punibilidade (inciso III); e à natureza da penalidade aplicável, ou à sua graduação (inciso IV).'),
(113,'','Obrigação tributária principal e acessória','A obrigação tributária é principal ou acessória. O § 1º dispõe que a obrigação principal surge com a ocorrência do fato gerador, tem por objeto o pagamento de tributo ou penalidade pecuniária e extingue-se juntamente com o crédito dela decorrente. O § 2º dispõe que a obrigação acessória decorre da legislação tributária e tem por objeto as prestações, positivas ou negativas, nela previstas no interesse da arrecadação ou da fiscalização dos tributos. O § 3º dispõe que a obrigação acessória, pelo simples fato da sua inobservância, converte-se em obrigação principal relativamente à penalidade pecuniária.'),
(113,'Art. 113-A','Razoabilidade e proporcionalidade das penalidades','As penalidades cominadas pela legislação em razão do descumprimento de obrigações tributárias principais e acessórias deverão observar o princípio da razoabilidade e guardar relação de proporcionalidade com a infração praticada pelo sujeito passivo (Lei Complementar n. 236, de 2026). O § 1º limita a multa, exceto as multas isoladas desvinculadas de valor de crédito ou tributo, a percentuais calculados sobre o valor do próprio tributo lançado ou do crédito cuja fiscalização tiver sido afetada pela desconformidade ou pelo atraso na prestação das informações: 75% (inciso I); 100% nos casos de prática dolosa de fraude, sonegação ou conluio (inciso II); e 150% nos casos de reincidência (inciso III). O § 2º consta como vetado e está registrado como não vigente.'),
(114,'','Fato gerador da obrigação principal','Fato gerador da obrigação principal é a situação definida em lei como necessária e suficiente à sua ocorrência.'),
(115,'','Fato gerador da obrigação acessória','Fato gerador da obrigação acessória é qualquer situação que, na forma da legislação aplicável, impõe a prática ou a abstenção de ato que não configure obrigação principal.'),
(116,'','Momento da ocorrência do fato gerador','Salvo disposição de lei em contrário, considera-se ocorrido o fato gerador e existentes os seus efeitos, tratando-se de situação de fato, desde o momento em que se verifiquem as circunstâncias materiais necessárias a que produza os efeitos que normalmente lhe são próprios (inciso I) e, tratando-se de situação jurídica, desde o momento em que esteja definitivamente constituída, nos termos de direito aplicável (inciso II). O parágrafo único, incluído pela Lei Complementar n. 104, de 2001, dispõe que a autoridade administrativa poderá desconsiderar atos ou negócios jurídicos praticados com a finalidade de dissimular a ocorrência do fato gerador do tributo ou a natureza dos elementos constitutivos da obrigação tributária, observados os procedimentos a serem estabelecidos em lei ordinária.'),
(117,'','Fato gerador sob negócios jurídicos condicionais','Para os efeitos do inciso II do artigo anterior e salvo disposição de lei em contrário, os atos ou negócios jurídicos condicionais reputam-se perfeitos e acabados, sendo suspensiva a condição, desde o momento de seu implemento (inciso I) e, sendo resolutória a condição, desde o momento da prática do ato ou da celebração do negócio (inciso II).'),
(118,'','Interpretação do fato gerador (abstração da validade e dos efeitos)','A definição legal do fato gerador é interpretada abstraindo-se da validade jurídica dos atos efetivamente praticados pelos contribuintes, responsáveis ou terceiros, bem como da natureza do seu objeto ou dos seus efeitos (inciso I), e dos efeitos dos fatos efetivamente ocorridos (inciso II).'),
(119,'','Sujeito ativo da obrigação tributária','Sujeito ativo da obrigação é a pessoa jurídica de direito público, titular da competência para exigir o seu cumprimento.'),
(120,'','Sub-rogação em caso de desmembramento territorial','Salvo disposição de lei em contrário, a pessoa jurídica de direito público que se constituir pelo desmembramento territorial de outra sub-roga-se nos direitos desta, cuja legislação tributária aplicará até que entre em vigor a sua própria.'),
(121,'','Sujeito passivo da obrigação principal','Sujeito passivo da obrigação principal é a pessoa obrigada ao pagamento de tributo ou penalidade pecuniária. O parágrafo único dispõe que o sujeito passivo da obrigação principal diz-se contribuinte, quando tenha relação pessoal e direta com a situação que constitua o respectivo fato gerador (inciso I), ou responsável, quando, sem revestir a condição de contribuinte, sua obrigação decorra de disposição expressa de lei (inciso II).'),
(122,'','Sujeito passivo da obrigação acessória','Sujeito passivo da obrigação acessória é a pessoa obrigada às prestações que constituam o seu objeto.'),
(123,'','Convenções particulares sobre responsabilidade tributária','Salvo disposições de lei em contrário, as convenções particulares, relativas à responsabilidade pelo pagamento de tributos, não podem ser opostas à Fazenda Pública, para modificar a definição legal do sujeito passivo das obrigações tributárias correspondentes.'),
(124,'','Solidariedade tributária','São solidariamente obrigadas as pessoas que tenham interesse comum na situação que constitua o fato gerador da obrigação principal (inciso I) e as pessoas expressamente designadas por lei (inciso II). O parágrafo único dispõe que a solidariedade referida no artigo não comporta benefício de ordem.'),
(125,'','Efeitos da solidariedade','Salvo disposição de lei em contrário, são efeitos da solidariedade: o pagamento efetuado por um dos obrigados aproveita aos demais (inciso I); a isenção ou remissão de crédito exonera todos os obrigados, salvo se outorgada pessoalmente a um deles, subsistindo, nesse caso, a solidariedade quanto aos demais pelo saldo (inciso II); e a interrupção da prescrição, em favor ou contra um dos obrigados, favorece ou prejudica aos demais (inciso III).'),
(126,'','Capacidade tributária passiva','A capacidade tributária passiva independe da capacidade civil das pessoas naturais (inciso I); de achar-se a pessoa natural sujeita a medidas que importem privação ou limitação do exercício de atividades civis, comerciais ou profissionais, ou da administração direta de seus bens ou negócios (inciso II); e de estar a pessoa jurídica regularmente constituída, bastando que configure uma unidade econômica ou profissional (inciso III).')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
